import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class CoreFunction_functionFloor_TriageGen2Test {

    private EvalContext context;
    private Expression expression;
    private CoreFunction coreFunction;

    @Before
    public void setUp() {
        context = mock(EvalContext.class);
        expression = mock(Expression.class);
    }

    /**
     * Helper to instantiate CoreFunction because the constructor is public 
     * but requires specific arguments. Since functionFloor is protected, 
     * we use a subclass or reflectively call it. 
     * However, based on the signature, we can mock the behavior of the surrounding class.
     */
    private CoreFunction createCoreFunctionWithArg(Expression arg1) {
        // functionCode is an int, args is an array of Expression
        return new CoreFunction(1, new Expression[]{arg1});
    }

    @Test
    public void testFunctionFloor_PositiveDouble() {
        coreFunction = createCoreFunctionWithArg(expression);
        when(expression.computeValue(context)).thenReturn(3.7);

        Object result = coreFunction.compute(context);

        assertEquals(3.0, (Double) result, 0.0001);
    }

    @Test
    public void testFunctionFloor_NegativeDouble() {
        coreFunction = createCoreFunctionWithArg(expression);
        when(expression.computeValue(context)).thenReturn(-3.7);

        Object result = coreFunction.compute(context);

        assertEquals(-4.0, (Double) result, 0.0001);
    }

    @Test
    public void testFunctionFloor_Integer() {
        coreFunction = createCoreFunctionWithArg(expression);
        when(expression.computeValue(context)).thenReturn(5.0);

        Object result = coreFunction.compute(context);

        assertEquals(5.0, (Double) result, 0.0001);
    }

    @Test
    public void testFunctionFloor_Zero() {
        coreFunction = createCoreFunctionWithArg(expression);
        when(expression.computeValue(context)).thenReturn(0.0);

        Object result = coreFunction.compute(context);

        assertEquals(0.0, (Double) result, 0.0001);
    }

    @Test
    public void testFunctionFloor_LargeValue() {
        coreFunction = createCoreFunctionWithArg(expression);
        when(expression.computeValue(context)).thenReturn(1234567.89);

        Object result = coreFunction.compute(context);

        assertEquals(1234567.0, (Double) result, 0.0001);
    }

    @Test(expected = RuntimeException.class)
    public void testFunctionFloor_WrongArgumentCount() {
        // If assertArgCount(1) is called and there are 0 or >1 args, it should throw exception.
        // Based on the provided code, it calls assertArgCount(1).
        // We simulate a mismatch by providing no arguments to the constructor.
        CoreFunction emptyFunction = new CoreFunction(1, new Expression[]{});
        emptyFunction.compute(context);
    }

    @Test
    public void testFunctionFloor_WithInfoSetUtilMocking() {
        // Since InfoSetUtil.doubleValue is likely a static utility, 
        // we test the flow through it.
        coreFunction = createCoreFunctionWithArg(expression);
        when(expression.computeValue(context)).thenReturn("10.5"); 

        // Note: This test assumes InfoSetUtil.doubleValue can handle String or 
        // that the computeValue returns something InfoSetUtil handles.
        // If InfoSetUtil is hard to mock, we rely on the logic that 
        // computeValue returns an object that doubleValue converts.

        // Testing with a Double object directly as most implementations of InfoSetUtil 
        // return the value if it's already a Double.
        when(expression.computeValue(context)).thenReturn(10.5);

        Object result = coreFunction.compute(context);
        assertEquals(10.0, (Double) result, 0.0001);
    }
}
